    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

// Register CTRL
reg [31:0] ctrl;

// Register STATUS
reg [31:0] status;

// Register IRQ
reg [31:0] irq;

// Register SCRATCH
reg [31:0] scratch;

// Pending IRQ bits
reg [31:0] pending_irq;

// Write valid mask
reg [3:0] wstrb_mask;

// Channel state
reg [1:0] write_channel_state;
reg [1:0] read_channel_state;

// B response valid
reg bvalid;

// R response valid
reg rvalid;

// R data
reg [31:0] rdata;

// B response
reg [1:0] bresp;

// R response
reg [1:0] rresp;

// Write channel state
reg [1:0] write_state;

// Read channel state
reg [1:0] read_state;

// Pending write
reg [31:0] pending_write;

// Pending read
reg [31:0] pending_read;

// IRQ set mask
reg [31:0] irq_set_mask;

always_comb begin
    // Determine write valid mask
    wstrb_mask = '0;
    for (int i = 0; i < 4; i++) begin
        if (s_axi_wstrb[i]) begin
            wstrb_mask |= 1 << i;
        end
    end
end

always_comb begin
    // Determine IRQ set mask
    irq_set_mask = '0;
    for (int i = 0; i < 32; i++) begin
        if (irq_set[i]) begin
            irq_set_mask |= 1 << i;
        end
    end
end

// Control logic
always @(posedge clk) begin
    // Reset control logic
    if (rst) begin
        ctrl <= '0;
        scratch <= '0;
        pending_irq <= '0;
        write_channel_state <= '0;
        read_channel_state <= '0;
        bvalid <= '0;
        rvalid <= '0;
        rdata <= '0;
        bresp <= '0;
        rresp <= '0;
        pending_write <= '0;
        pending_read <= '0;
        irq_set_mask <= '0;
        write_state <= '0;
        read_state <= '0;
    end else begin
        // Write channel logic
        if (s_axi_awvalid && s_axi_wvalid) begin
            if (write_channel_state == 2'b00) begin
                pending_write <= s_axi_wdata;
                write_state <= 2'b01;
            end
        end else if (write_state == 2'b01) begin
            write_channel_state <= 2'b10;
            bvalid <= 1'b1;
            bresp <= 2'b0;
        end

        // Read channel logic
        if (s_axi_arvalid) begin
            if (read_channel_state == 2'b00) begin
                pending_read <= s_axi_araddr;
                read_state <= 2'b01;
            end
        end else if (read_state == 2'b01) begin
            read_channel_state <= 2'b10;
            rvalid <= 1'b1;
            rdata <= pending_read[31:0];
            rresp <= 2'b0;
        end

        // IRQ logic
        if (irq_set) begin
            pending_irq <= pending_irq | irq_set_mask;
        end

        // CTRL logic
        if (s_axi_wvalid && s_axi_awaddr == 4'b0000) begin
            ctrl <= s_axi_wdata;
        end

        // STATUS logic
        if (s_axi_araddr == 4'b0004) begin
            status <= status_in;
        end

        // SCRATCH logic
        if (s_axi_wvalid && s_axi_awaddr == 4'b0008) begin
            scratch <= s_axi_wdata;
        end

        // IRQ logic
        if (s_axi_wvalid && s_axi_awaddr == 4'b000C) begin
            irq <= pending_irq & ~s_axi_wdata;
        end
    end
end

// Output logic
always_comb begin
    // Determine B response
    case ({write_state, read_channel_state})
        2'b01: begin
            bresp = 2'b0;
        end
        default: begin
            bresp = 2'b1;
        end
    end

    // Determine R response
    case ({read_state, write_channel_state})
        2'b01: begin
            rresp = 2'b0;
        end
        default: begin
            rresp = 2'b1;
        end
    end

    // Determine AXI4-Lite signals
    case ({write_state, read_channel_state})
        2'b00: begin
            s_axi_awready = 1'b1;
            s_axi_wready = 1'b1;
        end
        2'b01: begin
            s_axi_awready = 1'b0;
            s_axi_wready = 1'b0;
        end
        default: begin
            s_axi_awready = 1'b0;
            s_axi_wready = 1'b0;
        end
    end

    case ({read_state, write_channel_state})
        2'b00: begin
            s_axi_arready = 1'b1;
            s_axi_rvalid = 1'b0;
        end
        2'b01: begin
            s_axi_arready = 1'b0;
            s_axi_rvalid = 1'b1;
        end
        default: begin
            s_axi_arready = 1'b0;
            s_axi_rvalid = 1'b0;
        end
    end

    case ({write_state, read_channel_state})
        2'b00: begin
            s_axi_bvalid = 1'b0;
        end
        2'b01: begin
            s_axi_bvalid = bvalid;
        end
        default: begin
            s_axi_bvalid = 1'b0;
        end
    end

    case ({read_state, write_channel_state})
        2'b00: begin
            s_axi_rvalid = 1'b0;
        end
        2'b01: begin
            s_axi_rvalid = rvalid;
        end
        default: begin
            s_axi_rvalid = 1'b0;
        end
    end

    s_axi_rdata = pending_read[31:0];

    s_axi_bresp = bresp;
    s_axi_rresp = rresp;
end

endmodule

