        if (rst) begin
            ctrl_r <= '0;
            ctrl_w <= '0;
            scratch_r <= '0;
            scratch_w <= '0;
            irq_r <= '0;
            irq_w <= '0;
            status_valid <= '0;
            status_r <= '0;
            ctrl_w_valid <= '0;
            scratch_w_valid <= '0;
            irq_set_valid <= '0;
