    logic signed [2*WIDTH-1:0] b_reg [3];
    logic signed [2*WIDTH-1:0] prod_reg [3];
    logic [3:0] valid_reg;

    always_comb begin
        logic signed [2*WIDTH-1:0] prod;
        if (rst) begin
            prod = 0;
            out_valid = 0;
        end else begin
            if (in_valid) begin
                valid_reg = 3'b000;
