logic [3:0] gnt_reg;

always_ff @(posedge clk)
if (rst) begin
    last <= 3;
    gnt_reg <= 0;
end
else if (req == 4'b0001) begin
    gnt_reg <= 0;
    last <= last;
end
else begin
    logic [3:0] next_last;
    next_last = last + 1;
    next_last = next_last[3] ? 4'd0 : (next_last[2] ? next_last + 1 : (next_last[1] ? next_last + 1 : (next_last[0] ? next_last + 1 : last)));
    gnt_reg <= next_last[3] ? 4'b1000 : (next_last[2] ? 4'b01000 : (next_last[1] ? 4'b00100 : (next_last[0] ? 4'b00010 : 4'b00001)));
    last <= next_last;
end

assign gnt = gnt_reg;
endmodule

