    input  logic       load,
    input  logic [7:0] d,
    output logic [7:0] q
);
    logic [7:0] q_reg;

    always @(posedge clk)
    begin
        if (rst)
            q_reg <= 8'h0;
        else if (load)
            q_reg <= d;
        else if (en)
        begin
            if (up)
                q_reg <= q_reg + 8'h1;
            else
                q_reg <= (q_reg + 8'h1 == 8'h00) ? 8'h00 : q_reg - 8'h1;
        end
    end

    assign q = q_reg;
endmodule

