    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
// Register the input flit with valid
logic [4:0] slot_empty [4:0];
logic [5*(4+PAYLOAD_W)-1:0] slot_flit [4:0];
always_ff @(posedge clk) begin
    if (rst) begin
        for (int i = 0; i < 5; i++) begin
            slot_empty[i] <= 1'b1;
            slot_flit[i] <= 0;
        end
    end else if (in_valid != 0) begin
        for (int i = 0; i < 5; i++) begin
            if (in_valid[i] && slot_empty[i]) begin
                slot_empty[i] <= 1'b0;
                slot_flit[i] <= in_flit[i*(4+PAYLOAD_W)+: (4+PAYLOAD_W)];
            end
        end
    end
end
// Determine the next output based on the destination fields
logic [2:0] dest_x, dest_y;
logic [4:0] out_valid_req [4:0];
always_comb begin
    dest_x = in_flit[4+:2];
    dest_y = in_flit[6+:2];
    case ({dest_x, dest_y})
        3'b000: out_valid_req = 5'b10001; // L
