logic [4:0] cursor;
logic [4:0] next_cursor;
always_comb begin
    if (rst) cursor <= 5'b00100; // N
    else if (out_valid != 0) cursor <= next_cursor;
    next_cursor = cursor;
    for (int i = 0; i < 5; i++) begin
        if (out_valid_req[i] && (out_valid[i] || (slot_empty[i] && out_ready[i]))) begin
