module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

logic signed [9:0] bit_cnt; // 10-bit frame, including start and stop bits
logic signed [7:0] bit_data;
logic signed [7:0] shift_reg;

always_comb begin
    // Capture data on start rising edge, if not busy
    if (start && !busy) begin
        bit_data = data;
    end
    else begin
        bit_data = 8'd0; // Initialize bit_data to a known value
    end
end

always_ff @(posedge clk) begin
    if (rst) begin
        // Reset to idle
        tx <= 1;
        busy <= 0;
        bit_cnt <= 0;
        shift_reg <= 8'd0; // Initialize shift_reg to a known value
    end
    else begin
        // Idle
        if (start && !busy) begin
            // Start rising edge, capture data, begin frame
            tx <= 0;
            busy <= 1;
            bit_cnt <= 0;
            shift_reg <= {1'b0, bit_data}; // Initialize shift_reg with start bit
        end
        else if (busy) begin
            // Drive tx with the current bit
            tx <= shift_reg[0];
            // Increment bit counter
            bit_cnt <= bit_cnt + 1;
            // Shift bit data to the right
            shift_reg <= {shift_reg[7], shift_reg[6:0]};
            // Check end of frame
            if (bit_cnt == CLKS_PER_BIT * 10) begin
                // End of frame
                tx <= 1; // Fix: drive tx with 1 at the end of the frame
                busy <= 0;
            end
        end
        // Ignore new start while busy
        else if (start && busy) begin
            bit_data = data; // Capture new data while busy
        end
    end
end

endmodule

