module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

// Operation: Addition
always_comb begin
    case (op)
        3'b000: begin
            y = a + b;
            carry = (a[7] & b[7]) | (a[7] & y[7]) | (b[7] & y[7]);
        end
        // Operation: Subtraction
        3'b001: begin
            y = a - b;
            carry = (~a[7] & b[7]) | (~a[7] & y[7]) | (b[7] & y[7]);
        end
        // Operation: Bitwise AND
        3'b010: y = a & b;
        // Operation: Bitwise OR
        3'b011: y = a | b;
        // Operation: Bitwise XOR
        3'b100: y = a ^ b;
        // Operation: Set less than
        3'b101: begin
            if (~a[7] & b[7]) // Sign extension
                y = 8'd1;
            else
                y = 8'd0;
        end
        // Operation: Shift left
        3'b110: y = a << b[2:0];
        // Operation: Shift right
        3'b111: y = a >> b[2:0];
    endcase
end

// Zero flag
assign zero = (y == 8'd0);

endmodule

