module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

logic [3:0] state;

always @(posedge clk) begin
    if (rst) begin
        state <= 4'd0;
        match <= 1'b0;
    end else begin
        state[3] <= din;
        if (state[3] == 1'b1 && state[2] == 1'b0 && state[1] == 1'b1 && state[0] == 1'b1) begin
            match <= 1'b1;
            state <= 4'd0;
        end else begin
            match <= 1'b0;
        end
    end
end

endmodule

