    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

logic [3:0] data_reg; // 4-bit shift register to hold the last 4 bits sampled
logic match_reg;      // match signal register, one cycle delayed

always @(posedge clk) begin
    if (rst) begin
        data_reg <= 4'b0;
        match_reg <= 1'b0;
    end else begin
        // Shift the 4-bit register to the left, bringing the new din bit in
        data_reg <= {data_reg[3:1], din};

        // Check if the last four bits match the target pattern
        if (data_reg == 4'b1011) begin
            match_reg <= 1'b1;
        end else begin
            match_reg <= 1'b0;
        end
    end
end

// Assign match signal to output, with one cycle delay
assign match = match_reg;
endmodule

